<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { AlertTriangle, ArrowLeft, ArrowLeftRight, Check, ChevronLeft, ChevronRight, MapPin, PackagePlus, Pencil, Plus, Save, Search, Trash2, X } from 'lucide-vue-next';
import { api } from '../services/api';
import ProjectSearchSelect from '../components/ProjectSearchSelect.vue';
import { projects as demoProjects } from '../data/projects';
import { projectSites as demoSites } from '../data/projectSites';
import { unitOptions as demoUnits, type PurchaseLinePage, type PurchaseOption } from '../data/sitePurchases';
import { corporateCategories as demoCategories, corporateLines as demoPurchaseLines, corporateProducts as demoProducts, corporatePurchaseRecords as demoPurchases, type CorporateCategoryOption, type CorporateProductOption } from '../data/corporatePurchases';
import { corporateTransferLines, corporateTransferRecords, nextCorporateTransferId, nextCorporateTransferLineId, type CorporateTransferLineRecord, type CorporateTransferRecord } from '../data/corporateTransfers';

interface ProjectOption { id: number; code: string; name: string; tenderId: string; location: string }
interface SiteOption { id: number; projectId: number; name: string; address: string }
interface TransferOptions { projects: ProjectOption[]; sites: SiteOption[]; categories: CorporateCategoryOption[]; products: CorporateProductOption[]; units: PurchaseOption[] }

const route = useRoute(); const router = useRouter();
const editing = computed(() => route.name === 'corporate-transfer-edit'); const transferId = computed(() => Number(route.params.id));
const today = new Date().toISOString().slice(0, 10);
const projects = ref<ProjectOption[]>(demoProjects.map(({ id, code, name, tenderId, location }) => ({ id, code, name, tenderId, location })));
const sites = ref<SiteOption[]>(demoSites.map(({ id, projectId, name, address }) => ({ id, projectId, name, address })));
const categories = ref<CorporateCategoryOption[]>(demoCategories.filter((category) => demoProducts.some((product) => product.categoryId === category.id))); const products = ref<CorporateProductOption[]>([...demoProducts]); const units = ref<PurchaseOption[]>([...demoUnits]);
const loading = ref(false); const saving = ref(false); const saved = ref(''); const error = ref('');
const lines = ref<CorporateTransferLineRecord[]>([]); const lineSearch = ref(''); const linePage = ref(1); const lineTotalRows = ref(0); const pageSize = 20;
const lineFormOpen = ref(false); const lineSaving = ref(false); const productSearch = ref(''); const pendingLineDelete = ref<number | null>(null); const lineDeleting = ref(false);
const stockByProduct = ref<Record<number, number>>({}); const stockLoading = ref(false); const stockMessage = ref('');
const deleteOpen = ref(false); const deleteLoading = ref(false); const deleteCheck = ref<{ canDelete: boolean; references: { productLines: number } } | null>(null); const deleteText = ref(''); const deleting = ref(false);
const summary = reactive({ itemCount: 0, totalAmount: 0 });
const form = reactive({ transferNo: '', fromProjectId: Number(route.query.projectId || 0), fromSiteId: null as number | null, receiveProjectId: 0, receiveSiteId: null as number | null, transferDate: today, notes: '', status: 'posted' as 'draft' | 'posted' | 'cancelled' });
const lineForm = reactive({ id: null as number | null, categoryId: null as number | null, productId: 0, unitId: null as number | null, destinationSiteId: null as number | null, quantity: 1 as number | '', unitPrice: '' as number | '', otherCost: '' as number | '', otherExpense: '' as number | '', transferDate: '', notes: '' });

const sourceSites = computed(() => sites.value.filter((site) => site.projectId === form.fromProjectId));
const receiveSites = computed(() => sites.value.filter((site) => site.projectId === form.receiveProjectId));
const availableProducts = computed(() => { const term = productSearch.value.trim().toLowerCase(); if (!lineForm.categoryId) return []; return products.value.filter((item) => item.categoryId === lineForm.categoryId && (!term || item.name.toLowerCase().includes(term))); });
const selectedStock = computed(() => lineForm.productId ? Number(stockByProduct.value[lineForm.productId] ?? 0) : null);
const lineTotal = computed(() => Number(lineForm.quantity || 0) * Number(lineForm.unitPrice || 0) + Number(lineForm.otherCost || 0) + Number(lineForm.otherExpense || 0));
const linePageCount = computed(() => Math.max(1, Math.ceil(lineTotalRows.value / pageSize)));
function money(value: number) { return new Intl.NumberFormat('en-BD', { style: 'currency', currency: 'BDT', maximumFractionDigits: 2 }).format(Number(value)); }
function dateValue(value: unknown) { return value ? String(value).slice(0, 10) : ''; }
function fillHeader(item: CorporateTransferRecord) { form.transferNo = item.transferNo ?? ''; form.fromProjectId = Number(item.fromProjectId); form.fromSiteId = item.fromSiteId; form.receiveProjectId = Number(item.receiveProjectId); form.receiveSiteId = item.receiveSiteId; form.transferDate = dateValue(item.transferDate); form.notes = item.notes ?? ''; form.status = item.status; summary.itemCount = Number(item.itemCount); summary.totalAmount = Number(item.totalAmount); }
async function loadHeader() { if (!editing.value) return; if (import.meta.env.VITE_DEMO_MODE !== 'false') { const item = corporateTransferRecords.find((entry) => entry.id === transferId.value); if (item) fillHeader(item); return; } const result = await api<{ transfer: CorporateTransferRecord }>(`/corporate-transfers/${transferId.value}`); fillHeader(result.transfer); }
async function loadLines() { if (!editing.value) return; if (import.meta.env.VITE_DEMO_MODE !== 'false') { const term = lineSearch.value.trim().toLowerCase(); const matches = corporateTransferLines.filter((item) => item.transferId === transferId.value && (!term || [item.productName, item.categoryName, item.destinationSiteName, item.notes].some((value) => value.toLowerCase().includes(term)))); lineTotalRows.value = matches.length; lines.value = matches.slice((linePage.value - 1) * pageSize, linePage.value * pageSize).map((item) => ({ ...item })); return; } const result = await api<PurchaseLinePage<CorporateTransferLineRecord>>(`/corporate-transfers/${transferId.value}/lines?page=${linePage.value}&pageSize=${pageSize}&search=${encodeURIComponent(lineSearch.value)}`); lines.value = result.items; lineTotalRows.value = result.total; }
onMounted(async () => { loading.value = true; try { if (import.meta.env.VITE_DEMO_MODE === 'false') { const options = await api<TransferOptions>('/corporate-transfers/options'); projects.value = options.projects; sites.value = options.sites; categories.value = options.categories; products.value = options.products; units.value = options.units; } await loadHeader(); await loadLines(); } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Could not load corporate transfer.'; } finally { loading.value = false; } });
watch(() => form.fromProjectId, () => { if (form.fromSiteId && !sourceSites.value.some((site) => site.id === form.fromSiteId)) form.fromSiteId = null; });
watch(() => form.receiveProjectId, () => { if (form.receiveSiteId && !receiveSites.value.some((site) => site.id === form.receiveSiteId)) form.receiveSiteId = null; if (lineForm.destinationSiteId && !receiveSites.value.some((site) => site.id === lineForm.destinationSiteId)) lineForm.destinationSiteId = null; });
function demoStock(productId: number, lineId: number | null) {
  const siteMatches = (siteId: number | null) => !form.fromSiteId || siteId === form.fromSiteId;
  const purchased = demoPurchaseLines.filter((line) => { const header = demoPurchases.find((item) => item.id === line.purchaseId); return line.productId === productId && header?.projectId === form.fromProjectId && header.status === 'posted' && siteMatches(line.siteId ?? header.siteId); }).reduce((sum, line) => sum + line.quantity, 0);
  const received = corporateTransferLines.filter((line) => { const header = corporateTransferRecords.find((item) => item.id === line.transferId); return line.productId === productId && header?.receiveProjectId === form.fromProjectId && header.status === 'posted' && siteMatches(line.destinationSiteId ?? header.receiveSiteId); }).reduce((sum, line) => sum + line.quantity, 0);
  const sent = corporateTransferLines.filter((line) => { const header = corporateTransferRecords.find((item) => item.id === line.transferId); return line.productId === productId && line.id !== lineId && header?.fromProjectId === form.fromProjectId && header.status === 'posted' && siteMatches(header.fromSiteId); }).reduce((sum, line) => sum + line.quantity, 0);
  return Math.max(0, purchased + received - sent);
}
async function loadStock() {
  stockByProduct.value = {}; stockMessage.value = '';
  if (!lineForm.categoryId) return;
  stockLoading.value = true;
  try {
    if (import.meta.env.VITE_DEMO_MODE === 'false') {
      const suffix = lineForm.id ? `&lineId=${lineForm.id}` : '';
      const result = await api<{ stock: { productId: number; availableStock: number }[] }>(`/corporate-transfers/${transferId.value}/stock?categoryId=${lineForm.categoryId}${suffix}`);
      stockByProduct.value = Object.fromEntries(result.stock.map((item) => [item.productId, Number(item.availableStock)]));
    } else {
      stockByProduct.value = Object.fromEntries(availableProducts.value.map((item) => [item.id, demoStock(item.id, lineForm.id)]));
    }
  } catch (reason) { stockMessage.value = reason instanceof Error ? reason.message : 'Could not check source stock.'; }
  finally { stockLoading.value = false; }
}
async function categoryChanged() { if (lineForm.productId && !products.value.some((item) => item.id === lineForm.productId && item.categoryId === lineForm.categoryId)) lineForm.productId = 0; await loadStock(); }
function productChanged() { const product = products.value.find((item) => item.id === lineForm.productId); if (!product) return; lineForm.categoryId = product.categoryId; lineForm.unitId = product.unitId ?? null; if (product.defaultPrice !== null && product.defaultPrice !== undefined) lineForm.unitPrice = Number(product.defaultPrice); }
function resetLineForm() { Object.assign(lineForm, { id: null, categoryId: null, productId: 0, unitId: null, destinationSiteId: form.receiveSiteId, quantity: 1, unitPrice: '', otherCost: '', otherExpense: '', transferDate: form.transferDate, notes: '' }); productSearch.value = ''; }
function addLine() { error.value = ''; resetLineForm(); stockByProduct.value = {}; stockMessage.value = ''; lineFormOpen.value = true; }
function closeLineForm() { lineFormOpen.value = false; error.value = ''; }
async function editLine(item: CorporateTransferLineRecord) { error.value = ''; Object.assign(lineForm, { id: item.id, categoryId: item.categoryId, productId: item.productId ?? 0, unitId: item.unitId, destinationSiteId: item.destinationSiteId, quantity: Number(item.quantity), unitPrice: Number(item.unitPrice), otherCost: Number(item.otherCost), otherExpense: Number(item.otherExpense), transferDate: dateValue(item.transferDate), notes: item.notes ?? '' }); productSearch.value = ''; lineFormOpen.value = true; await loadStock(); }

async function saveHeader() {
  if (!form.fromProjectId || !form.receiveProjectId || !form.transferDate) { error.value = 'Source project, receiving project, and transfer date are required.'; return; }
  if (form.fromProjectId === form.receiveProjectId && form.fromSiteId && form.fromSiteId === form.receiveSiteId) { error.value = 'For a site-to-site transfer, source and receiving sites must be different.'; return; }
  saving.value = true; error.value = ''; saved.value = '';
  try { let id = transferId.value; const payload = { ...form, fromSiteId: form.fromSiteId || null, receiveSiteId: form.receiveSiteId || null }; if (import.meta.env.VITE_DEMO_MODE === 'false') { const result = await api<{ id: number }>(editing.value ? `/corporate-transfers/${id}` : '/corporate-transfers', { method: editing.value ? 'PUT' : 'POST', body: JSON.stringify(payload) }); id = result.id; } else { const fromProject = projects.value.find((item) => item.id === form.fromProjectId)!; const receiveProject = projects.value.find((item) => item.id === form.receiveProjectId)!; const fromSite = sites.value.find((item) => item.id === form.fromSiteId); const receiveSite = sites.value.find((item) => item.id === form.receiveSiteId); if (!editing.value) id = nextCorporateTransferId(); const record: CorporateTransferRecord = { id, transferNo: form.transferNo, transferDate: form.transferDate, notes: form.notes, fromProjectId: form.fromProjectId, fromProjectName: fromProject.name, fromProjectCode: fromProject.code, fromSiteId: form.fromSiteId, fromSiteName: fromSite?.name ?? '', receiveProjectId: form.receiveProjectId, receiveProjectName: receiveProject.name, receiveProjectCode: receiveProject.code, receiveSiteId: form.receiveSiteId, receiveSiteName: receiveSite?.name ?? '', status: form.status, itemCount: summary.itemCount, totalQuantity: 0, totalAmount: summary.totalAmount }; const index = corporateTransferRecords.findIndex((item) => item.id === id); if (index >= 0) corporateTransferRecords[index] = record; else corporateTransferRecords.unshift(record); } saved.value = editing.value ? 'Corporate transfer updated.' : 'Corporate transfer created. Add material lines below.'; if (!editing.value) await router.replace(`/purchases/transfers/${id}/edit`); }
  catch (reason) { error.value = reason instanceof Error ? reason.message : 'Could not save the corporate transfer.'; } finally { saving.value = false; }
}
async function saveLine() {
  if (!lineForm.categoryId || !lineForm.productId || Number(lineForm.quantity) <= 0 || lineForm.unitPrice === '') { error.value = 'Select a category and corporate product, then enter a valid quantity and price.'; return; }
  if (selectedStock.value !== null && Number(lineForm.quantity) > selectedStock.value + 0.00005) { error.value = `Insufficient source stock. Available: ${selectedStock.value.toLocaleString()} ${units.value.find((item) => item.id === lineForm.unitId)?.name ?? ''}.`; return; }
  lineSaving.value = true; error.value = '';
  try { const payload = { categoryId: lineForm.categoryId, productId: lineForm.productId, unitId: lineForm.unitId, destinationSiteId: lineForm.destinationSiteId, quantity: Number(lineForm.quantity), unitPrice: Number(lineForm.unitPrice), otherCost: Number(lineForm.otherCost || 0), otherExpense: Number(lineForm.otherExpense || 0), transferDate: lineForm.transferDate, notes: lineForm.notes }; if (import.meta.env.VITE_DEMO_MODE === 'false') await api(lineForm.id ? `/corporate-transfers/${transferId.value}/lines/${lineForm.id}` : `/corporate-transfers/${transferId.value}/lines`, { method: lineForm.id ? 'PUT' : 'POST', body: JSON.stringify(payload) }); else { const product = products.value.find((item) => item.id === payload.productId)!; const category = categories.value.find((item) => item.id === payload.categoryId); const unit = units.value.find((item) => item.id === payload.unitId); const site = sites.value.find((item) => item.id === payload.destinationSiteId); const record: CorporateTransferLineRecord = { id: lineForm.id ?? nextCorporateTransferLineId(), transferId: transferId.value, categoryId: payload.categoryId, categoryName: category?.name ?? '', productId: product.id, productName: product.name, unitId: payload.unitId, unitName: unit?.name ?? '', destinationSiteId: payload.destinationSiteId, destinationSiteName: site?.name ?? '', quantity: payload.quantity, unitPrice: payload.unitPrice, otherCost: payload.otherCost, otherExpense: payload.otherExpense, totalAmount: lineTotal.value, notes: payload.notes, transferDate: payload.transferDate }; const index = corporateTransferLines.findIndex((item) => item.id === record.id); if (index >= 0) corporateTransferLines[index] = record; else corporateTransferLines.unshift(record); const transfer = corporateTransferRecords.find((item) => item.id === transferId.value); const allLines = corporateTransferLines.filter((item) => item.transferId === transferId.value); if (transfer) { transfer.itemCount = allLines.length; transfer.totalQuantity = allLines.reduce((sum, item) => sum + item.quantity, 0); transfer.totalAmount = allLines.reduce((sum, item) => sum + item.totalAmount, 0); fillHeader(transfer); } } lineFormOpen.value = false; resetLineForm(); await loadLines(); if (import.meta.env.VITE_DEMO_MODE === 'false') await loadHeader(); }
  catch (reason) { error.value = reason instanceof Error ? reason.message : 'Could not save the transfer line.'; } finally { lineSaving.value = false; }
}
async function confirmLineDelete() { if (!pendingLineDelete.value) return; lineDeleting.value = true; try { if (import.meta.env.VITE_DEMO_MODE === 'false') await api(`/corporate-transfers/${transferId.value}/lines/${pendingLineDelete.value}`, { method: 'DELETE' }); else { const index = corporateTransferLines.findIndex((item) => item.id === pendingLineDelete.value); if (index >= 0) corporateTransferLines.splice(index, 1); } pendingLineDelete.value = null; await loadLines(); await loadHeader(); } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Could not delete the transfer line.'; pendingLineDelete.value = null; } finally { lineDeleting.value = false; } }
async function checkDelete() { deleteOpen.value = true; deleteText.value = ''; deleteCheck.value = null; deleteLoading.value = true; try { deleteCheck.value = import.meta.env.VITE_DEMO_MODE === 'false' ? await api(`/corporate-transfers/${transferId.value}/delete-check`) : { canDelete: summary.itemCount === 0, references: { productLines: summary.itemCount } }; } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Could not check transfer references.'; deleteOpen.value = false; } finally { deleteLoading.value = false; } }
async function removeTransfer() { if (!deleteCheck.value?.canDelete || deleteText.value !== 'DELETE') return; deleting.value = true; try { if (import.meta.env.VITE_DEMO_MODE === 'false') await api(`/corporate-transfers/${transferId.value}`, { method: 'DELETE' }); else { const index = corporateTransferRecords.findIndex((item) => item.id === transferId.value); if (index >= 0) corporateTransferRecords.splice(index, 1); } await router.push('/purchases/transfers'); } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Could not delete the corporate transfer.'; deleteOpen.value = false; } finally { deleting.value = false; } }
</script>

<template>
  <section class="project-form-page corporate-transfer-form-page">
    <div class="form-page-head"><RouterLink to="/purchases/transfers" class="back-link"><ArrowLeft :size="16" /> All corporate transfers</RouterLink><div><span class="form-heading-icon"><ArrowLeftRight :size="21" /></span><span><h2>{{ editing ? 'Corporate transfer' : 'New corporate transfer' }}</h2><p>Save the route first, then add all product lines in the popup.</p></span></div></div>
    <form class="project-form panel purchase-header-form" @submit.prevent="saveHeader"><div v-if="loading" class="site-form-loading">Loading corporate transfer…</div><div class="form-section-title"><span>01</span><div><h3>Transfer route</h3><p>Move products project-to-project, site-to-site, or between a project and a site.</p></div></div><div class="form-grid transfer-route-grid">
      <label class="form-field"><span>Transfer number</span><div><input v-model="form.transferNo" placeholder="Transfer reference" /></div></label><label class="form-field"><span>Transfer date <b>*</b></span><div><input v-model="form.transferDate" type="date" /></div></label><label class="form-field"><span>Status</span><select v-model="form.status"><option value="posted">Posted</option><option value="draft">Draft</option><option value="cancelled">Cancelled</option></select></label>
      <div class="transfer-endpoint"><strong><MapPin :size="15" /> Source</strong><label class="form-field"><span>From project <b>*</b></span><ProjectSearchSelect v-model="form.fromProjectId" :projects="projects" /></label><label class="form-field"><span>From site</span><select v-model="form.fromSiteId"><option :value="null">Whole project / not specified</option><option v-for="site in sourceSites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label></div>
      <div class="transfer-arrow"><ArrowLeftRight :size="24" /></div>
      <div class="transfer-endpoint"><strong><MapPin :size="15" /> Receiving</strong><label class="form-field"><span>To project <b>*</b></span><ProjectSearchSelect v-model="form.receiveProjectId" :projects="projects" /></label><label class="form-field"><span>To site</span><select v-model="form.receiveSiteId"><option :value="null">Set per product line / not specified</option><option v-for="site in receiveSites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label></div>
      <label class="form-field full"><span>Notes</span><div><input v-model="form.notes" placeholder="Transfer or receiving notes" /></div></label>
    </div><p v-if="error" class="form-error form-message">{{ error }}</p><p v-if="saved" class="save-success"><Check :size="16" />{{ saved }}</p><footer class="form-actions"><button v-if="editing" type="button" class="delete-project-button" @click="checkDelete"><Trash2 :size="16" /> Delete transfer</button><RouterLink to="/purchases/transfers" class="secondary-button">Cancel</RouterLink><button class="primary-button" :disabled="saving"><Save :size="17" />{{ saving ? 'Saving…' : editing ? 'Save transfer' : 'Create transfer' }}</button></footer></form>

    <section v-if="editing" class="purchase-entries panel"><header class="purchase-entry-summary"><div><button class="active"><PackagePlus :size="17" /><span><strong>Transferred products</strong><small>{{ summary.itemCount }} lines</small></span></button></div><strong>{{ money(summary.totalAmount) }} total</strong></header><div class="purchase-entry-toolbar"><label class="table-search"><Search :size="16" /><input v-model="lineSearch" placeholder="Search product, category, or destination…" @keyup.enter="linePage = 1; loadLines()" /></label><button type="button" class="secondary-button" @click="linePage = 1; loadLines()"><Search :size="15" /> Search</button><button type="button" class="primary-button" @click="addLine"><Plus :size="16" /> Add product</button></div>
      <div class="purchase-lines-table-wrap"><table class="site-table purchase-lines-table transfer-lines-table"><thead><tr><th>Product</th><th>Category</th><th>Destination site</th><th>Quantity</th><th>Unit price</th><th>Other cost</th><th>Other expense</th><th>Total</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="item in lines" :key="item.id"><td data-label="Product"><strong>{{ item.productName }}</strong><small>{{ item.notes }}</small></td><td data-label="Category">{{ item.categoryName || '—' }}</td><td data-label="Destination">{{ item.destinationSiteName || (form.receiveSiteId ? 'Header receiving site' : 'Receiving project') }}</td><td data-label="Quantity">{{ Number(item.quantity).toLocaleString() }} {{ item.unitName }}</td><td data-label="Unit price">{{ money(item.unitPrice) }}</td><td data-label="Other cost">{{ money(item.otherCost) }}</td><td data-label="Other expense">{{ money(item.otherExpense) }}</td><td data-label="Total"><strong>{{ money(item.totalAmount) }}</strong></td><td data-label="Actions"><div class="line-actions"><button type="button" @click="editLine(item)"><Pencil :size="14" /></button><button type="button" class="danger" @click="pendingLineDelete = item.id"><Trash2 :size="14" /></button></div></td></tr><tr v-if="!lines.length"><td colspan="9"><div class="site-empty"><PackagePlus :size="22" /><strong>No transferred products found</strong><span>Add the first material line to this transfer.</span></div></td></tr></tbody></table></div><footer class="table-pagination purchase-line-pagination"><span>{{ lineTotalRows }} matching product lines</span><div><button type="button" :disabled="linePage === 1" @click="linePage--; loadLines()"><ChevronLeft :size="16" /></button><span>Page {{ linePage }} of {{ linePageCount }}</span><button type="button" :disabled="linePage === linePageCount" @click="linePage++; loadLines()"><ChevronRight :size="16" /></button></div></footer>
    </section>

    <div v-if="lineFormOpen" class="modal-backdrop" @click.self="closeLineForm"><form class="purchase-line-form purchase-line-modal corporate-line-form" @submit.prevent="saveLine"><header><div><PackagePlus :size="18" /><span><strong>{{ lineForm.id ? 'Modify transfer line' : 'Add transferred product' }}</strong><small>Select a category first. Quantity is checked against source stock before saving.</small></span></div><button type="button" @click="closeLineForm"><X :size="17" /></button></header><div class="form-grid three"><label class="form-field"><span>Category <b>*</b></span><select v-model="lineForm.categoryId" @change="categoryChanged"><option :value="null" disabled>Select category</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="form-field"><span>Find product</span><div><Search :size="15" /><input v-model="productSearch" :disabled="!lineForm.categoryId" placeholder="Type product name…" /></div></label><label class="form-field"><span>Corporate product <b>*</b></span><select v-model.number="lineForm.productId" :disabled="!lineForm.categoryId || stockLoading" @change="productChanged"><option :value="0" disabled>{{ !lineForm.categoryId ? 'Select category first' : stockLoading ? 'Checking source stock…' : `Select product (${availableProducts.length} in category)` }}</option><option v-for="item in availableProducts" :key="item.id" :value="item.id" :disabled="Number(stockByProduct[item.id] ?? 0) <= 0">{{ item.name }}{{ item.unitName ? ` — ${item.unitName}` : '' }} — stock {{ Number(stockByProduct[item.id] ?? 0).toLocaleString() }}</option></select></label><div class="stock-check full" :class="{ unavailable: selectedStock !== null && selectedStock <= 0 }"><PackagePlus :size="17" /><span v-if="stockLoading">Checking source project/site stock…</span><span v-else-if="stockMessage">{{ stockMessage }}</span><span v-else-if="selectedStock !== null">Available source stock: <strong>{{ selectedStock.toLocaleString() }} {{ units.find((item) => item.id === lineForm.unitId)?.name ?? '' }}</strong></span><span v-else>Select a category and product to see available source stock.</span></div><label class="form-field"><span>Destination site</span><select v-model="lineForm.destinationSiteId"><option :value="null">Use header receiving site / project</option><option v-for="site in receiveSites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label class="form-field"><span>UOM</span><select v-model="lineForm.unitId"><option :value="null">No UOM</option><option v-for="unit in units" :key="unit.id" :value="unit.id">{{ unit.name }}</option></select></label><label class="form-field"><span>Line date</span><div><input v-model="lineForm.transferDate" type="date" /></div></label><label class="form-field"><span>Quantity <b>*</b></span><div><input v-model.number="lineForm.quantity" type="number" min="0.0001" :max="selectedStock ?? undefined" step="0.0001" /></div></label><label class="form-field"><span>Unit price <b>*</b></span><div><input v-model.number="lineForm.unitPrice" type="number" min="0" step="0.0001" /></div></label><label class="form-field"><span>Other cost</span><div><input v-model.number="lineForm.otherCost" type="number" min="0" step="0.01" /></div></label><label class="form-field"><span>Other expense</span><div><input v-model.number="lineForm.otherExpense" type="number" min="0" step="0.01" /></div></label><label class="form-field full"><span>Notes</span><div><input v-model="lineForm.notes" placeholder="Optional line notes" /></div></label></div><p v-if="error" class="form-error modal-error">{{ error }}</p><footer><span>Calculated total <strong>{{ money(lineTotal) }}</strong></span><button type="button" class="secondary-button" @click="closeLineForm">Cancel</button><button class="primary-button" :disabled="lineSaving || stockLoading || selectedStock === null || selectedStock <= 0"><Check :size="15" />{{ lineSaving ? 'Saving…' : lineForm.id ? 'Update product' : 'Add product' }}</button></footer></form></div>
    <div v-if="pendingLineDelete" class="modal-backdrop" @click.self="pendingLineDelete = null"><section class="delete-modal"><button class="modal-close" @click="pendingLineDelete = null"><X :size="18" /></button><span class="delete-modal-icon"><AlertTriangle :size="24" /></span><h2>Delete this transfer line?</h2><p>This removes only the selected product from the transfer.</p><div class="modal-actions"><button class="secondary-button" @click="pendingLineDelete = null">Cancel</button><button class="danger-button" :disabled="lineDeleting" @click="confirmLineDelete"><Trash2 :size="16" />{{ lineDeleting ? 'Deleting…' : 'Delete line' }}</button></div></section></div>
    <div v-if="deleteOpen" class="modal-backdrop" @click.self="deleteOpen = false"><section class="delete-modal"><button class="modal-close" @click="deleteOpen = false"><X :size="18" /></button><span class="delete-modal-icon"><AlertTriangle :size="24" /></span><h2>Delete this corporate transfer?</h2><p v-if="deleteLoading">Checking product lines…</p><template v-else-if="deleteCheck && !deleteCheck.canDelete"><div class="delete-blocked"><AlertTriangle :size="18" /><span><strong>Deletion prevented</strong><small>Remove all product lines before deleting the transfer header.</small></span></div><div class="reference-list"><div><span>Product lines</span><strong>{{ deleteCheck.references.productLines }}</strong></div></div><button class="secondary-button modal-done" @click="deleteOpen = false">Close</button></template><template v-else-if="deleteCheck"><p>No product lines were found. Type DELETE to confirm.</p><label class="delete-confirm-field"><span>Type <b>DELETE</b> to confirm</span><input v-model="deleteText" placeholder="DELETE" /></label><div class="modal-actions"><button class="secondary-button" @click="deleteOpen = false">Cancel</button><button class="danger-button" :disabled="deleteText !== 'DELETE' || deleting" @click="removeTransfer"><Trash2 :size="16" />{{ deleting ? 'Deleting…' : 'Delete transfer' }}</button></div></template></section></div>
  </section>
</template>
